phase1.code:
use std::time::Duration;

// ---- async functions ----
// An async function returns a Future
async fn hello() -> String {
    "Hello, world!".to_string()
}

// ---- async with sleep ----
// This is a simplified example (without Tokio)
// In real code, you'd use tokio::time::sleep
async fn delayed_message(seconds: u64, message: String) -> String {
    // Simulate async wait
    // tokio::time::sleep(Duration::from_secs(seconds)).await;
    format!("{} (after {} seconds)", message, seconds)
}

// ---- async with multiple awaits ----
async fn fetch_data() -> String {
    let part1 = async { "Hello".to_string() }.await;
    let part2 = async { "World".to_string() }.await;
    format!("{} {}", part1, part2)
}

// ---- async with error handling ----
async fn fetch_with_error() -> Result<String, &'static str> {
    // Simulate potential failure
    let success = true;
    if success {
        Ok("Data received".to_string())
    } else {
        Err("Failed to fetch data")
    }
}

// ---- main is not async by default ----
// We need a runtime to run async code
fn main() {
    // In a real app, you'd use:
    // #[tokio::main]
    // async fn main() { ... }

    println!("Async functions defined, but not executed without a runtime.");
    println!("In the next lessons, we'll use Tokio to run them.");
}

